<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from "vue";
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { open } from "@tauri-apps/plugin-dialog";

type Status = "pending" | "running" | "completed" | "failed" | "cancelled";
interface VideoFile { path:string; relativePath:string; name:string; codec:string; resolution:string; durationSecs:number; bitrateBps:number; sizeBytes:number; needsProcessing:boolean; action:"transcode"|"remux"|"skip"; reason:string; selected?:boolean; status?:Status; progress?:number; result?:string; outputBytes?:number }
interface JobEvent { kind:"started"|"progress"|"completed"|"failed"|"cancelled"|"batch-finished"; path?:string; index:number; total:number; progress:number; message:string; originalBytes?:number; outputBytes?:number }

const folder=ref(""); const files=ref<VideoFile[]>([]); const scanning=ref(false); const running=ref(false);
const errorMessage=ref(""); const toolStatus=ref("正在检查 FFmpeg..."); const batchMessage=ref("尚未开始");
const batchIndex=ref(0); const batchTotal=ref(0); const batchSavedBytes=ref(0); const batchCompleted=ref(0); const logs=ref<string[]>([]); const runLogs=ref<string[]>([]); const showOnlyNeeded=ref(true);
const rules=reactive({minBitrateMbps:0,minFileSizeMb:20,transcodeH264:true,unwantedExtensions:"mov, avi, wmv, flv"});
const settings=reactive({encoder:"hevc_nvenc",preset:"p5",cq:28,pixelFormat:"p010le",replaceIfLarger:false,saveLogs:true});
let unlisten:UnlistenFn|undefined;

const visibleFiles=computed(()=>showOnlyNeeded.value?files.value.filter(f=>f.needsProcessing):files.value);
const selectedFiles=computed(()=>files.value.filter(f=>f.needsProcessing&&f.selected));
const needCount=computed(()=>files.value.filter(f=>f.needsProcessing).length);
const selectedBytes=computed(()=>selectedFiles.value.reduce((sum,f)=>sum+f.sizeBytes,0));
const batchProgress=computed(()=>batchTotal.value?Math.min(100,((Math.max(0,batchIndex.value-1)+(files.value.find(f=>f.status==="running")?.progress??0)/100)/batchTotal.value)*100):0);
const commandTemplate=computed(()=>{const pixelFormat=settings.encoder==="libx265"&&settings.pixelFormat==="p010le"?"yuv420p10le":settings.pixelFormat;const video=settings.encoder==="hevc_nvenc"?`-c:v hevc_nvenc -preset ${settings.preset} -profile:v main10 -rc vbr -cq ${settings.cq} -pix_fmt ${pixelFormat}`:`-c:v libx265 -preset ${settings.preset} -crf ${settings.cq} -pix_fmt ${pixelFormat}`;return `ffmpeg -hide_banner -y -i "<输入文件>" -map 0:v:0 -map 0:a? -map_metadata 0 -map_chapters 0 ${video} -c:a copy -movflags +faststart -progress pipe:1 -nostats "<临时输出.mp4>"`});

function formatBytes(bytes:number){if(!bytes)return"0 B";const u=["B","KB","MB","GB","TB"],i=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),u.length-1);return`${(bytes/1024**i).toFixed(i>=3?2:1)} ${u[i]}`}
function formatDuration(s:number){if(!s)return"--";const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=Math.floor(s%60);return[h,m,x].map((v,i)=>i?String(v).padStart(2,"0"):String(v)).join(":")}
function formatBitrate(b:number){return b?`${(b/1e6).toFixed(1)} Mbps`:"未知"}
function logLine(message:string){return `[${new Date().toLocaleString("zh-CN",{hour12:false})}] ${message}`}
function addLog(message:string){logs.value.unshift(logLine(message));logs.value=logs.value.slice(0,100)}
function addRunLog(message:string){const line=logLine(message);runLogs.value.push(line);logs.value.unshift(line);logs.value=logs.value.slice(0,100)}
function logFilename(){const now=new Date(),part=(value:number,length=2)=>String(value).padStart(length,"0");return `m5ga-${now.getFullYear()}${part(now.getMonth()+1)}${part(now.getDate())}-${part(now.getHours())}${part(now.getMinutes())}${part(now.getSeconds())}-${part(now.getMilliseconds(),3)}.log`}
async function chooseFolder(){const selected=await open({directory:true,multiple:false,title:"选择待扫描的视频目录"});if(typeof selected==="string"){folder.value=selected;files.value=[];errorMessage.value=""}}
async function scan(){if(!folder.value){errorMessage.value="请先选择目录";return}scanning.value=true;errorMessage.value="";batchMessage.value="正在递归读取视频信息...";try{const result=await invoke<VideoFile[]>("scan_videos",{request:{root:folder.value,minBitrateMbps:rules.minBitrateMbps,minFileSizeMb:rules.minFileSizeMb,transcodeH264:rules.transcodeH264,unwantedExtensions:rules.unwantedExtensions.split(",")}});files.value=result.map(f=>({...f,selected:f.needsProcessing,status:"pending",progress:0}));batchMessage.value=`扫描完成：发现 ${result.length} 个视频，${needCount.value} 个需要处理`;addLog(batchMessage.value)}catch(e){errorMessage.value=String(e);batchMessage.value="扫描失败"}finally{scanning.value=false}}
function selectAll(value:boolean){files.value.forEach(f=>{if(f.needsProcessing&&f.status!=="completed")f.selected=value})}
async function start(){if(!selectedFiles.value.length){errorMessage.value="请至少选择一个待处理文件";return}errorMessage.value="";batchSavedBytes.value=0;batchCompleted.value=0;runLogs.value=[];selectedFiles.value.forEach(f=>{f.status="pending";f.progress=0;f.result=""});try{const {saveLogs,...encodeSettings}=settings;await invoke("start_transcode",{request:{files:selectedFiles.value.map(f=>({path:f.path,action:f.action,durationSecs:f.durationSecs})),settings:encodeSettings}});running.value=true;batchIndex.value=1;batchTotal.value=selectedFiles.value.length;batchMessage.value="任务已启动";addRunLog(`开始处理 ${batchTotal.value} 个文件`);addRunLog(`扫描目录：${folder.value}`);addRunLog(`FFmpeg 命令模板：${commandTemplate.value}`);if(!saveLogs)addRunLog("本次未启用日志文件保存") }catch(e){errorMessage.value=String(e)}}
async function cancel(){await invoke("cancel_transcode");batchMessage.value="正在停止当前任务..."}
async function handleEvent(e:JobEvent){batchIndex.value=e.index;batchTotal.value=e.total;batchMessage.value=e.message;if(e.kind==="batch-finished"){running.value=false;const summary=`${e.message}：成功 ${batchCompleted.value} 个，总计节省 ${formatBytes(batchSavedBytes.value)}`;batchMessage.value=summary;addRunLog(summary);if(settings.saveLogs){try{const path=await invoke<string>("save_run_log",{filename:logFilename(),content:`${runLogs.value.join("\r\n")}\r\n`});addLog(`日志已保存：${path}`)}catch(error){const message=`日志保存失败：${String(error)}`;errorMessage.value=message;addLog(message)}}return}const f=files.value.find(x=>x.path===e.path);if(!f)return;if(e.kind==="started"){f.status="running";f.progress=0;addRunLog(`${e.index}/${e.total} ${f.relativePath}：${e.message}`)}else if(e.kind==="progress")f.progress=e.progress;else if(e.kind==="completed"){const saved=Math.max(0,(e.originalBytes??0)-(e.outputBytes??0));batchCompleted.value+=1;batchSavedBytes.value+=saved;f.status="completed";f.progress=100;f.outputBytes=e.outputBytes;f.result=e.message;f.selected=false;addRunLog(`${f.relativePath} 完成，节省 ${formatBytes(saved)}`)}else{f.status=e.kind==="cancelled"?"cancelled":"failed";f.result=e.message;addRunLog(`${f.relativePath}：${e.message}`)}}
onMounted(async()=>{unlisten=await listen<JobEvent>("transcode-event",e=>handleEvent(e.payload));try{toolStatus.value=await invoke<string>("check_tools")}catch(e){toolStatus.value=String(e);errorMessage.value=toolStatus.value}});onUnmounted(()=>unlisten?.());
watch(()=>settings.encoder,encoder=>{settings.preset=encoder==="hevc_nvenc"?"p5":"medium"});
</script>

<template><div class="app-shell">
<header class="topbar"><div><p class="eyebrow">LOCAL VIDEO TRANSCODER</p><h1>M5GA</h1><p class="subtitle">批量整理高码率和不兼容封装的视频，然后安全替换源文件。</p></div><div class="tool-state" :class="{bad:errorMessage&&toolStatus===errorMessage}"><span class="dot"></span><div><small>运行环境</small><strong>{{toolStatus}}</strong></div></div></header>
<main>
<section class="panel"><Heading number="01" title="选择视频目录" description="会递归扫描所有子目录，不跟随目录链接。"/><div class="folder-row"><button class="folder-field" :disabled="running" @click="chooseFolder"><b>⌁</b><span>{{folder||"点击选择目录"}}</span></button><button class="primary" :disabled="!folder||scanning||running" @click="scan">{{scanning?"扫描中...":files.length?"重新扫描":"开始扫描"}}</button></div></section>
<div class="settings-grid"><section class="panel"><Heading number="02" title="筛选规则" description="容器规则独立生效；码率和大小阈值仅用于 H.264 转码。"/><label class="toggle"><span><strong>H.264 转 H.265</strong><small>同时满足码率和文件大小阈值时转码</small></span><input v-model="rules.transcodeH264" type="checkbox" :disabled="running"></label><label class="field"><span>最低码率，0 则不限制码率</span><div class="suffix"><input v-model.number="rules.minBitrateMbps" type="number" min="0" :disabled="running"><i>Mbps</i></div></label><label class="field"><span>文件大小阈值</span><div class="suffix"><input v-model.number="rules.minFileSizeMb" type="number" min="0" :disabled="running"><i>MB</i></div><small>小于此大小的 H.264 不转码；0 则不限制大小。</small></label><label class="field"><span>不需要的封装</span><input v-model="rules.unwantedExtensions" :disabled="running"><small>容器规则不受码率或文件大小限制；H.265 源只换封装，其他编码会转码。</small></label></section>
<section class="panel"><Heading number="03" title="编码设置" description="默认采用你的 NVENC 参数。"/><div class="two"><label class="field"><span>编码器</span><select v-model="settings.encoder" :disabled="running"><option value="hevc_nvenc">NVIDIA NVENC</option><option value="libx265">CPU x265</option></select></label><label class="field"><span>Preset</span><select v-model="settings.preset" :disabled="running"><template v-if="settings.encoder==='hevc_nvenc'"><option v-for="p in ['p1','p2','p3','p4','p5','p6','p7']" :key="p">{{p}}</option></template><template v-else><option v-for="p in ['ultrafast','fast','medium','slow','slower']" :key="p">{{p}}</option></template></select></label></div><div class="two"><label class="field"><span>{{settings.encoder==='hevc_nvenc'?'CQ':'CRF'}}</span><input v-model.number="settings.cq" type="number" min="0" max="51" :disabled="running"></label><label class="field"><span>像素格式</span><select v-model="settings.pixelFormat" :disabled="running"><option value="p010le">10-bit p010le</option><option value="yuv420p">8-bit yuv420p</option></select></label></div><label class="toggle subtle"><span><strong>输出更大时仍替换</strong><small>建议关闭，避免越转越大。</small></span><input v-model="settings.replaceIfLarger" type="checkbox" :disabled="running"></label><label class="toggle subtle"><span><strong>保存本次运行日志</strong><small>队列结束后保存到 %APPDATA%\m5ga</small></span><input v-model="settings.saveLogs" type="checkbox" :disabled="running"></label><div class="command-preview"><span>FFmpeg 命令模板</span><code>{{commandTemplate}}</code></div></section></div>
<section v-if="files.length" class="panel queue"><div class="queue-head"><div><h2>文件队列</h2><p>共 {{files.length}} 个，{{needCount}} 个待处理，已选 {{selectedFiles.length}} 个（{{formatBytes(selectedBytes)}}）</p></div><div class="tools"><label><input v-model="showOnlyNeeded" type="checkbox"> 仅显示待处理</label><button @click="selectAll(true)" :disabled="running">全选</button><button @click="selectAll(false)" :disabled="running">清空</button></div></div><div class="table-wrap"><table><thead><tr><th></th><th>文件</th><th>视频信息</th><th>大小 / 时长</th><th>处理原因</th><th>状态</th></tr></thead><tbody><tr v-for="f in visibleFiles" :key="f.path" :class="[`status-${f.status}`,{muted:!f.needsProcessing}]"><td><input v-model="f.selected" type="checkbox" :disabled="!f.needsProcessing||running||f.status==='completed'"></td><td><strong :title="f.path">{{f.name}}</strong><small>{{f.relativePath}}</small></td><td><b class="codec">{{f.codec.toUpperCase()}}</b><small>{{f.resolution}} · {{formatBitrate(f.bitrateBps)}}</small></td><td><strong>{{formatBytes(f.outputBytes??f.sizeBytes)}}</strong><small>{{formatDuration(f.durationSecs)}}</small></td><td><b :class="['action',f.action]">{{f.action==='transcode'?'转码':f.action==='remux'?'换封装':'跳过'}}</b><small>{{f.reason}}</small></td><td><span>{{f.status==='running'?`${f.progress?.toFixed(1)}%`:f.status==='completed'?'已完成':f.status==='failed'?'失败':f.status==='cancelled'?'已取消':'等待'}}</span><div v-if="f.status==='running'" class="progress"><i :style="{width:`${f.progress}%`}"></i></div><small v-if="f.result" :title="f.result">{{f.result}}</small></td></tr></tbody></table></div></section>
<section class="run-panel"><div class="run-status"><div class="run-copy"><b>{{running?`${batchIndex} / ${batchTotal}`:'READY'}}</b><span><strong>{{batchMessage}}</strong><small>先生成并校验临时 MP4，成功后才替换源文件。</small></span></div><div v-if="running" class="progress"><i :style="{width:`${batchProgress}%`}"></i></div></div><button v-if="!running" class="start" :disabled="!selectedFiles.length||scanning" @click="start">开始处理 {{selectedFiles.length?`(${selectedFiles.length})`:''}}</button><button v-else class="cancel" @click="cancel">停止任务</button></section>
<p v-if="errorMessage" class="error">{{errorMessage}}</p><details v-if="logs.length" class="logs"><summary>运行日志（{{logs.length}}）</summary><pre>{{logs.join('\n')}}</pre></details>
</main></div></template>

<script lang="ts">
import { defineComponent, h } from "vue";
const Heading=defineComponent({props:{number:String,title:String,description:String},setup:p=>()=>h("div",{class:"heading"},[h("b",p.number),h("div",[h("h2",p.title),h("p",p.description)])])});
export default {components:{Heading}};
</script>

<style>
:root{font-family:"Segoe UI","Microsoft YaHei UI",sans-serif;color:#e9eef5;background:#0a0d11;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:880px;min-height:100vh;background:radial-gradient(circle at 12% -10%,#1c2931 0,transparent 34%),#0a0d11}button,input,select{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}.app-shell{width:min(1500px,100%);margin:auto;padding:34px 42px 50px}.topbar{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:28px}.eyebrow{color:#5ee4b2;font-weight:800;font-size:11px;letter-spacing:.22em;margin:0 0 5px}h1{font-size:42px;line-height:1;margin:0;letter-spacing:-.04em}.subtitle{color:#8996a5;margin:10px 0 0}.tool-state{display:flex;align-items:center;gap:10px;max-width:410px;padding:11px 14px;border:1px solid #253039;border-radius:8px;background:#10151a}.tool-state div{display:flex;flex-direction:column;min-width:0}.tool-state small{color:#697684}.tool-state strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:#5ee4b2;box-shadow:0 0 12px #5ee4b2}.bad .dot{background:#ff746c}main{display:grid;gap:16px}.panel{background:#11161bea;border:1px solid #252e36;border-radius:10px;padding:22px;box-shadow:0 18px 50px #0003}.heading{display:flex;gap:14px;align-items:flex-start;margin-bottom:20px}.heading>b{display:grid;place-items:center;width:30px;height:30px;border:1px solid #3c5b51;color:#5ee4b2;border-radius:5px;font:700 12px ui-monospace}.heading h2,h2{font-size:16px;margin:0}.heading p,.queue-head p{color:#798694;font-size:12px;margin:3px 0 0}.folder-row{display:flex;gap:10px}.folder-field{flex:1;min-width:0;display:flex;gap:10px;align-items:center;text-align:left;padding:12px 14px;color:#c9d2da;background:#0c1014;border:1px solid #2b363f;border-radius:6px}.folder-field span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.folder-field b{color:#5ee4b2;font-size:23px}.primary,.start{border:0;border-radius:6px;color:#07110d;background:#5ee4b2;font-weight:800;padding:0 23px}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.toggle{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #242d34}.toggle span{display:flex;flex-direction:column}.toggle small,.field small{color:#6f7c88;margin-top:3px}.toggle input{appearance:none;width:36px;height:20px;border-radius:20px;padding:2px;background:#37414a}.toggle input:after{content:"";display:block;width:16px;height:16px;border-radius:50%;background:white;transition:.2s}.toggle input:checked{background:#43c99a}.toggle input:checked:after{transform:translateX(16px)}.toggle.subtle{border:0;padding-bottom:0}.field{display:flex;flex-direction:column;gap:7px;color:#9ba6b0;font-size:12px;margin-top:14px}.field input,.field select{width:100%;color:#e9eef5;background:#0b0f13;border:1px solid #2a353e;border-radius:5px;padding:9px 10px;outline:none}.field input:focus,.field select:focus{border-color:#4bb68f}.suffix{position:relative}.suffix i{position:absolute;right:10px;top:9px;color:#66737e;font-style:normal}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.queue{padding:0;overflow:hidden}.queue-head{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;border-bottom:1px solid #263039}.tools{display:flex;align-items:center;gap:9px;font-size:12px;color:#8b97a2}.tools button{color:#b5c0ca;background:transparent;border:1px solid #34404a;border-radius:5px;padding:6px 10px}.table-wrap{max-height:400px;overflow:auto}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px}th{position:sticky;top:0;z-index:1;color:#687581;background:#0d1115;font-weight:600;text-align:left;padding:9px 12px}th:first-child{width:42px}th:nth-child(2){width:28%}th:nth-child(3){width:15%}th:nth-child(4){width:12%}th:nth-child(5){width:23%}td{padding:12px;border-top:1px solid #202830;vertical-align:middle}td strong,td small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}td small{color:#6f7b86;margin-top:4px}tr.muted{opacity:.46}tr.status-running{background:#46c99b0d}tr.status-failed{background:#ff5a5a0d}.codec{color:#a9d7c6;font:700 11px ui-monospace}.action{display:inline-block;border-radius:3px;padding:2px 6px}.action.transcode{color:#5ee4b2;background:#17382e}.action.remux{color:#82b8ff;background:#182d48}.action.skip{color:#89939b;background:#282d31}.progress{height:3px;margin-top:7px;background:#263039;overflow:hidden;border-radius:3px}.progress i{display:block;height:100%;background:#5ee4b2;transition:width .2s}.run-panel{position:sticky;bottom:12px;display:flex;gap:12px;padding:11px;background:#0a0e12f0;border:1px solid #303b44;border-radius:10px;backdrop-filter:blur(14px);box-shadow:0 12px 40px #000}.run-status{flex:1;display:flex;flex-direction:column;justify-content:center;min-width:0;padding:2px 8px}.run-copy{display:flex;gap:12px;align-items:center}.run-copy>b{color:#5ee4b2;font:700 11px ui-monospace}.run-copy span{min-width:0;display:flex;flex-direction:column}.run-copy strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.run-copy small{color:#697681;margin-top:2px}.start,.cancel{min-width:185px;min-height:52px}.cancel{color:#ff938d;background:#311c1d;border:1px solid #6e3432;border-radius:6px;font-weight:700}.error{margin:0;color:#ffaea9;background:#291718;border:1px solid #5b2928;border-radius:7px;padding:11px 14px;white-space:pre-wrap}.logs{color:#83909b;font-size:12px}.logs summary{cursor:pointer}.logs pre{max-height:220px;overflow:auto;padding:12px;background:#080b0e;border:1px solid #202930;border-radius:6px;white-space:pre-wrap}@media(max-width:1000px){.app-shell{padding:25px}.settings-grid{grid-template-columns:1fr}.tool-state{max-width:300px}}
.command-preview{margin-top:16px}.command-preview>span{display:block;color:#7f8b96;font-size:12px;margin-bottom:7px}.command-preview code{display:block;max-height:96px;overflow:auto;padding:10px 12px;color:#a9d7c6;background:#080c0f;border:1px solid #27323a;border-radius:5px;font:11px/1.55 ui-monospace,"Cascadia Mono",monospace;white-space:pre-wrap;overflow-wrap:anywhere}
</style>
